<script setup lang="ts">
import { ref, watch, onScopeDispose } from 'vue';
import { useHookFetch } from 'hook-fetch/vue';
import { send } from '@/api/chat';
import { create_session } from '@/api/session';
import { getAgentList } from '@/api/agent';
import type { AgentVO } from '@/api/agent/types';
import { readMediaApiResult } from '@/api/media/response';
import { lawyerRequest, type CaseFile } from '@/api/lawyer';
import { caseFiles } from '@/api/lawyer/materials';
import { useUserStore } from '@/stores';
import { decodeReviewEvents, sessionIdFrom } from '@/pages/contract-review/workflow';
import { downloadMinutes, type DossierBundle, type DossierAnswer } from '@/pages/cases/dossier';
import LegalAnswer from './LegalAnswer.vue';
const props=defineProps<{caseId:string;caseTitle:string;disabled?:boolean}>(),emit=defineEmits<{busy:[value:boolean]}>();
const user=useUserStore(),files=ref<CaseFile[]>([]),selected=ref<string[]>([]),bundle=ref<DossierBundle>(),answers=ref<DossierAnswer[]>([]),question=ref('争议焦点是什么？'),current=ref(''),sessionId=ref(''),busy=ref(false),error=ref('');
const {stream,cancel}=useHookFetch({request:send});let version=0,disposed=false;
async function refresh(){const v=++version;files.value=[];selected.value=[];bundle.value=undefined;answers.value=[];sessionId.value='';current.value='';error.value='';try{const result=await caseFiles(props.caseId);if(!disposed&&v===version)files.value=result;}catch(e){if(v===version)error.value=(e as Error).message;}}
async function run(action:(active:()=>boolean)=>Promise<void>){if(busy.value||props.disabled||!user.token)return;const v=version,owner=user.token;const active=()=>!disposed&&v===version&&owner===user.token;busy.value=true;emit('busy',true);error.value='';try{await action(active);}catch(e){if(active())error.value=(e as Error).message;}finally{if(active()){busy.value=false;emit('busy',false);}}}
function parse(){void run(async active=>{if(!selected.value.length)throw Error('请先选择已归档的案件材料');const result=await lawyerRequest<{data:DossierBundle}>(`/lawyer/case/${props.caseId}/dossier/parse`,'POST',{fileIds:selected.value},240000);if(active())bundle.value=result.data;});}
function ask(){void run(async active=>{if(!bundle.value||!bundle.value.documents.some(d=>d.status==='success'||d.status==='partial'))throw Error('请先解析材料，至少一份成功后可提问');const q=question.value.trim();if(!q)throw Error('请填写阅卷问题');const agents=await readMediaApiResult<AgentVO[]>(getAgentList());if(!active())return;const agent=agents.data.find(a=>a.agentName==='法律咨询助手'&&a.status==='0');if(!agent)throw Error('法律咨询助手暂不可用');if(!sessionId.value){const created=await readMediaApiResult<unknown>(create_session({sessionTitle:('案件阅卷 - '+props.caseTitle).slice(0,100),caseId:props.caseId}));if(!active())return;sessionId.value=sessionIdFrom(created.data);}current.value='';let done=false;const materials=bundle.value.documents.map(({name,status,characters})=>({name,status,characters}));for await(const chunk of stream({model:agent.modelName||'',agentId:agent.id,sessionId:sessionId.value,content:q,dossierCaseId:props.caseId,dossierFileIds:[...selected.value],enableThinking:false})){if(!active())return;for(const event of decodeReviewEvents(chunk)){if(event.event==='error'||event.error)throw Error(String(event.error||'阅卷失败'));if('code' in event&&event.code!==200)throw Error(String(event.msg||'阅卷失败'));if(typeof event.content==='string')current.value+=event.content;if(event.done===true||event.event==='done')done=true;}}if(!done||!current.value.trim())throw Error('未收到完整回答，请重试');answers.value.push({question:q,answer:current.value,documents:materials});current.value='';});}
watch(selected,()=>{bundle.value=undefined;},{deep:true});
watch(()=>[props.caseId,user.token],()=>{cancel();busy.value=false;emit('busy',false);void refresh();},{immediate:true,flush:'sync'});
onScopeDispose(()=>{disposed=true;version++;cancel();emit('busy',false);});
</script>
<template><section class="dossier"><h3>法律阅卷</h3><p>先在“材料”页上传并归档，再选择多份材料解析。默认单次最多6份、合计5万字；实际限制以服务器提示为准。PDF、DOCX与清晰图片可解析，扫描PDF无文字时会明确失败。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-checkbox-group v-model="selected" :disabled="busy||disabled"><el-checkbox v-for="file in files" :key="file.ossId" :value="file.ossId" :label="file.ossId">{{file.originalName||file.fileName}}</el-checkbox></el-checkbox-group><el-empty v-if="!files.length" description="暂无材料，请先到材料页上传" :image-size="50"/><el-space wrap><el-button :disabled="busy||disabled" @click="refresh">刷新材料</el-button><el-button type="primary" :loading="busy" :disabled="!selected.length||busy||disabled" @click="parse">解析所选材料</el-button></el-space><div v-if="bundle"><p>共{{bundle.totalCharacters}}字；上限{{bundle.maxFiles}}份 / {{bundle.maxCharacters}}字</p><ul><li v-for="doc in bundle.documents" :key="doc.ossId">{{doc.name}} · {{doc.type}} · {{doc.status==='success'?'解析成功':doc.status==='partial'?'部分解析，仅使用成功页':'解析失败'}} · {{doc.characters}}字 <span v-if="doc.error">{{doc.error}}</span></li></ul></div><label for="dossier-question">阅卷问题</label><el-input id="dossier-question" v-model="question" type="textarea" :rows="3" maxlength="2000" :disabled="busy||disabled"/><el-space wrap><el-button type="primary" :disabled="!bundle||busy||disabled" :loading="busy" @click="ask">基于材料提问</el-button><el-button :disabled="!answers.length||busy||disabled" @click="downloadMinutes(caseTitle,answers)">下载阅卷纪要（Markdown）</el-button></el-space><p v-if="sessionId">问答会话已关联本案件，可从关联会话重新查看；本页刷新后请从会话中查阅历史回答。</p><article v-for="(item,i) in answers" :key="i"><h4>{{item.question}}</h4><LegalAnswer :content="item.answer"/></article><LegalAnswer v-if="current" :content="current"/></section></template>
<style scoped>.dossier{line-height:1.8}.dossier>p{font-size:13px;color:var(--el-text-color-secondary)}.el-checkbox-group{display:flex;flex-direction:column;margin:12px 0}.el-checkbox{height:auto;white-space:normal}.el-space{margin:12px 0}label{display:block;margin-top:16px}article{border-top:1px solid var(--el-border-color);padding:16px 0;overflow-wrap:anywhere}</style>
